import {FormEvent,useEffect,useMemo,useRef,useState} from 'react';
import {Bell,CalendarDays,ChevronRight,ClipboardList,FlaskConical,FolderKanban,LayoutDashboard,Loader2,LogOut,Menu,Plus,Search,TriangleAlert,Truck,X} from 'lucide-react';
import type {Session} from '@supabase/supabase-js';
import {supabase} from './supabase';import {apiUrl,apiFetch,setApiToken} from './api'; import type {AttEntry,DocEntry,ExpEntry,Item,NotionIssue,NotionProject,Project,SkillEntry} from './types';
type Page='dashboard'|'projects'|'requirements'|'validation'|'tasks'|'risks'|'handover'|'issues'|'experience'|'attendance'|'official'|'unofficial'/*|'skills' 2026-11-27 暂时隐藏团队能力矩阵，需要时解开此注释恢复*/;
// 2026-11-26 暂时隐藏空的 AMR 子页面（需求/技术验证/任务/风险/移交），后续按需恢复时解开下方注释即可
const nav:[Page,string,typeof LayoutDashboard][]=[['dashboard','总览',LayoutDashboard],['projects','项目',FolderKanban],
/* ['requirements','需求',ClipboardList],['validation','技术验证',FlaskConical],['tasks','任务',ClipboardList],['risks','风险',TriangleAlert],['handover','移交',Truck], */
['issues','问题追踪看板',Bell],
['experience','问题与经验库',ClipboardList],['attendance','员工出勤日历',CalendarDays],['official','官方技术资料',FlaskConical],['unofficial','非官方技术资料',Truck]/*,['skills','团队能力矩阵',LayoutDashboard] 2026-11-27 暂时隐藏团队能力矩阵，需要时解开此注释恢复 */];
const tables={requirements:'requirements',validation:'test_cases',tasks:'tasks',risks:'risks',handover:'handover_items'} as const;
const titles={requirements:'需求管理',validation:'技术验证',tasks:'任务管理',risks:'风险管理',handover:'项目移交'} as const;
const msg=(e:unknown)=>e instanceof Error?e.message:'操作失败，请稍后重试';
function Pill({children}:{children:string}){return <span className={'pill '+(/严重|FAIL|高/.test(children)?'red':/中|进行中|Open|BLOCKED/.test(children)?'yellow':'green')}>{children}</span>}
function Empty(){return <div className="empty"><FolderKanban/><b>暂无数据</b><span>点击右上角按钮创建第一条记录。</span></div>}
function Auth(){const [reg,setReg]=useState(false),[busy,setBusy]=useState(false),[note,setNote]=useState('');async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();if(!supabase)return;setBusy(true);setNote('');const f=new FormData(e.currentTarget),email=String(f.get('email')),password=String(f.get('password')),full_name=String(f.get('name'));const {error}=reg?await supabase.auth.signUp({email,password,options:{data:{full_name}}}):await supabase.auth.signInWithPassword({email,password});setBusy(false);setNote(error?error.message:reg?'注册成功，请检查邮箱并确认后登录。':'');}return <div className="auth"><section><div className="authbrand"><b>H</b><span>AMR PROJECT<small>MANAGEMENT SYSTEM</small></span></div><h1>{reg?'创建账户':'欢迎回来'}</h1><p>{reg?'注册后即可参与项目协作。':'登录后管理项目、需求、验证、任务、风险与移交。'}</p><form onSubmit={submit}>{reg&&<label>姓名<input name="name" required/></label>}<label>邮箱<input name="email" type="email" required/></label><label>密码<input name="password" type="password" minLength={6} required/></label>{note&&<div className="formnotice">{note}</div>}<button className="primary" disabled={busy}>{busy&&<Loader2 className="spin"/>}{reg?'注册':'登录'}</button></form><button className="link" onClick={()=>{setReg(!reg);setNote('')}}>{reg?'已有账户？返回登录':'没有账户？立即注册'}</button></section></div>}
function ProjectForm({value,close,saved,notice}:{value?:Project;close:()=>void;saved:()=>void;notice:(s:string)=>void}){async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();if(!supabase)return;const f=new FormData(e.currentTarget),data={name:String(f.get('name')),customer:String(f.get('customer')),description:String(f.get('description')),status:String(f.get('status')),risk:String(f.get('risk')),progress:Number(f.get('progress')),start_date:String(f.get('start'))||null,delivery_date:String(f.get('delivery'))||null};const {error}=value?await supabase.from('projects').update(data).eq('id',value.id):await supabase.from('projects').insert(data);if(error)return notice(msg(error));saved();close()}return <div className="overlay"><form className="modal" onSubmit={submit}><div className="modalhead"><h2>{value?'编辑项目':'新建项目'}</h2><button type="button" className="icon" onClick={close}><X/></button></div><div className="formgrid"><label>项目名称<input name="name" defaultValue={value?.name} required/></label><label>客户<input name="customer" defaultValue={value?.customer} required/></label><label>阶段<select name="status" defaultValue={value?.status||'需求分析'}>{['需求分析','技术验证','现场实施','已交付'].map(x=><option key={x}>{x}</option>)}</select></label><label>风险<select name="risk" defaultValue={value?.risk||'低'}>{['低','中','高','严重'].map(x=><option key={x}>{x}</option>)}</select></label><label>进度<input name="progress" type="number" min="0" max="100" defaultValue={value?.progress||0}/></label><label>开始日期<input name="start" type="date" defaultValue={value?.start_date||''}/></label><label>交付日期<input name="delivery" type="date" defaultValue={value?.delivery_date||''}/></label><label className="wide">说明<textarea name="description" defaultValue={value?.description||''}/></label></div><div className="actions"><button type="button" className="outline" onClick={close}>取消</button><button className="primary">保存</button></div></form></div>}
function ItemForm({page,projects,close,saved,notice}:{page:'requirements'|'validation'|'tasks'|'risks'|'handover';projects:Project[];close:()=>void;saved:()=>void;notice:(s:string)=>void}){async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();if(!supabase)return;const f=new FormData(e.currentTarget),base={project_id:String(f.get('project')),title:String(f.get('title'))},detail=String(f.get('detail'));let data:any=base;if(page==='requirements')data={...base,detail,priority:String(f.get('priority')),status:'待确认'};if(page==='validation')data={...base,objective:detail,result:'NOT_RUN'};if(page==='tasks')data={...base,notes:detail,status:'待处理'};if(page==='risks')data={...base,mitigation:detail,severity:String(f.get('priority')),probability:'中',status:'Open'};if(page==='handover')data={...base,category:String(f.get('priority')),completed:false};const {error}=await supabase.from(tables[page]).insert(data);if(error)return notice(msg(error));saved();close()}return <div className="overlay"><form className="modal small" onSubmit={submit}><div className="modalhead"><h2>新增{titles[page]}</h2><button type="button" className="icon" onClick={close}><X/></button></div><label>所属项目<select name="project" required><option value="">请选择</option>{projects.map(p=><option value={p.id} key={p.id}>{p.name}</option>)}</select></label><label>标题<input name="title" required/></label><label>说明<textarea name="detail"/></label>{(page==='requirements'||page==='risks'||page==='handover')&&<label>{page==='handover'?'分类':'优先级'}<select name="priority">{(page==='handover'?['Documentation','Testing','Training','Final']:['低','中','高','严重']).map(x=><option key={x}>{x}</option>)}</select></label>}<div className="actions"><button type="button" className="outline" onClick={close}>取消</button><button className="primary">保存</button></div></form></div>}
function Table({rows,open}:{rows:Project[];open:(p:Project)=>void}){return <div className="card table"><div className="scroll"><table><thead><tr><th>项目</th><th>客户</th><th>阶段</th><th>进度</th><th>风险</th><th/></tr></thead><tbody>{rows.map(p=><tr key={p.id} onClick={()=>open(p)}><td><b>{p.name}</b><span>{p.description||'暂无说明'}</span></td><td>{p.customer}</td><td><Pill>{p.status}</Pill></td><td><div className="progress"><span><i style={{width:p.progress+'%'}}/></span><b>{p.progress}%</b></div></td><td><Pill>{p.risk}</Pill></td><td><ChevronRight/></td></tr>)}</tbody></table></div>{!rows.length&&<Empty/>}</div>}
function Title({name,sub,add}:{name:string;sub:string;add:()=>void}){return <div className="title"><div><h1>{name}</h1><p>{sub}</p></div><button className="primary" onClick={add}><Plus/>新增</button></div>}
type IssueView='table'|'board';
type IssueFilters={status:string;priority:string;owner:string;difficulty:string};
const ALL='全部';
function IssueFiltersBar({filters,set,issues}:{filters:IssueFilters;set:(f:IssueFilters)=>void;issues:NotionIssue[]}){
 const uniq=(xs:(string|null)[])=>[ALL,...Array.from(new Set(xs.filter(Boolean) as string[]))];
 const cur=(v:string,f:string)=>v===ALL?f==='':v===f;
 return <div className="issuefilters">
  <span className="iflabel">状态</span>{uniq(issues.map(i=>i.status)).map(s=><button key={s} className={cur(s,filters.status)?'iftag on':'iftag'} onClick={()=>set({...filters,status:s===ALL?'':s})}>{s}</button>)}
  <span className="iflabel">优先级</span>{uniq(issues.map(i=>i.priority)).map(s=><button key={s} className={cur(s,filters.priority)?'iftag on':'iftag'} onClick={()=>set({...filters,priority:s===ALL?'':s})}>{s}</button>)}
  <span className="iflabel">技术难度</span>{uniq(issues.map(i=>i.techDifficulty||null)).map(s=><button key={s} className={cur(s,filters.difficulty)?'iftag on':'iftag'} onClick={()=>set({...filters,difficulty:s===ALL?'':s})}>{s}</button>)}
  <span className="iflabel">负责人</span>{uniq(issues.map(i=>i.owner)).map(s=><button key={s} className={cur(s,filters.owner)?'iftag on':'iftag'} onClick={()=>set({...filters,owner:s===ALL?'':s})}>{s}</button>)}
 </div>}
const ISSUE_STATUSES=['Doing','Waiting','Done','Closed'] as const;
function IssueDetail({issue,close,notice,refresh}:{issue:NotionIssue;close:()=>void;notice:(s:string)=>void;refresh:()=>void}){
 const [edit,setEdit]=useState(false),[text,setText]=useState(issue.content||''),[busy,setBusy]=useState(false);
 const [files,setFiles]=useState<{id:string;name:string;path:string}[]>([]),[addFile,setAddFile]=useState(false),[fname,setFname]=useState(''),[fpath,setFpath]=useState('');
 async function loadFiles(){try{const r=await apiFetch(`${apiUrl('list-files')}&page_id=${issue.id}`);const d=await r.json();setFiles(d.files||[])}catch{}}
 useEffect(()=>{loadFiles()},[issue.id]);
 async function saveFile(){if(!fname.trim()||!fpath.trim())return notice('文件名和 OneDrive 路径都要填');setBusy(true);try{const r=await apiFetch(apiUrl('add-file'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({notion_page_id:issue.id,name:fname.trim(),path:fpath.trim()})});const e=await r.json().catch(()=>({}));if(!r.ok)notice(e.error||`登记失败 ${r.status}`);else{notice('已登记并写回 Notion');setAddFile(false);setFname('');setFpath('');loadFiles();refresh()}}finally{setBusy(false)}}
 async function delFile(id:string){if(!confirm('确认删除这条文件记录吗？（不影响 OneDrive 原文件）'))return;const r=await apiFetch(apiUrl('delete-file'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});if(r.ok)loadFiles();else notice('删除失败')}
 function copyPath(path:string){navigator.clipboard.writeText(path).then(()=>notice('路径已复制，去 OneDrive 粘贴打开'),()=>notice('复制失败，请手动选择复制'))}
 async function saveContent(){setBusy(true);try{const r=await apiFetch(apiUrl('update-content'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({notion_page_id:issue.id,content:text})});if(!r.ok){const e=await r.json().catch(()=>({}));notice(e.error||`保存失败 ${r.status}`)}else{notice('已保存并写回 Notion');setEdit(false);refresh()}}finally{setBusy(false)}}
 return <div className="overlay" onClick={e=>{if(e.target===e.currentTarget)close()}}><div className="modal issuedetail"><div className="modalhead"><h2>{issue.code}</h2><button type="button" className="icon" onClick={close}><X/></button></div>
 <div className="idmeta">{[['状态',issue.status],['优先级',issue.priority],['技术难度',issue.techDifficulty||'—'],['负责人',issue.owner],['所属项目',issue.project||'—'],['客户',issue.customer],['创建',issue.createdDate||'—'],['解决',issue.resolvedDate||'—']].map(([k,v])=><div key={k}><dt>{k}</dt><dd>{v}</dd></div>)}</div>
 <div className="idactions">{edit?<>
   <button className="outline" onClick={()=>{setEdit(false);setText(issue.content||'')}}>取消</button>
   <button className="primary" disabled={busy} onClick={saveContent}>{busy?'保存中…':'保存到 Notion'}</button>
  </>:<>
   <button className="outline" onClick={()=>{setEdit(true);setText(issue.content||'')}}>编辑正文</button>
   {issue.pageUrl&&<a className="outline linkbtn" href={issue.pageUrl} target="_blank" rel="noreferrer">在 Notion 打开 ↗</a>}
  </>}</div>
 <div className="idbody">{edit?<textarea value={text} onChange={e=>setText(e.target.value)} className="idtextarea"/>:issue.content?issue.content.split(/\n/).map((l,i)=><p key={i}>{l||' '}</p>):<p className="idempty">暂无正文内容</p>}</div>
 <div className="idfiles"><div className="idfileshead"><b>📎 文件索引</b><small>文件存 OneDrive，此处登记标题与路径</small><button className="outline" onClick={()=>setAddFile(!addFile)}>{addFile?'取消':'登记文件'}</button></div>
 {addFile&&<div className="fileform"><input placeholder="文件标题，如：告警信息表V8.1.pdf" value={fname} onChange={e=>setFname(e.target.value)}/><input placeholder="OneDrive 路径" value={fpath} onChange={e=>setFpath(e.target.value)}/><button className="primary" disabled={busy} onClick={saveFile}>{busy?'登记中…':'登记'}</button></div>}
 {files.length?files.map(f=><div className="filerow" key={f.id}><b>{f.name}</b><code title={f.path}>{f.path}</code><button className="link" onClick={()=>copyPath(f.path)}>复制路径</button><button className="textdanger" onClick={()=>delFile(f.id)}>删除</button></div>):<div className="idempty">暂无文件</div>}
 </div>
 </div></div>}
function IssueBoard({issues,open,dragEnd,dragging,setDragging}:{issues:NotionIssue[];open:(i:NotionIssue)=>void;dragEnd:(id:string,status:string)=>void;dragging:string|null;setDragging:(v:string|null)=>void}){const groups=[['Doing','进行中'],['Waiting','等待'],['Done','已解决'],['Closed','已关闭']] as const;return <div className="issueboard">{groups.map(([k,label])=><div className="ibcol" key={k} onDragOver={e=>{e.preventDefault()}} onDrop={e=>{e.preventDefault();const id=e.dataTransfer.getData('text/plain');if(id)dragEnd(id,k)}}><div className="ibcolhead"><b>{label} ({k})</b><span>{issues.filter(i=>i.status===k).length}</span></div>{issues.filter(i=>i.status===k).map(i=><div className={'ibcard'+(dragging===i.id?' dragging':'')} key={i.id} draggable onDragStart={e=>{e.dataTransfer.setData('text/plain',i.id);setDragging(i.id)}} onDragEnd={()=>setDragging(null)} onClick={()=>open(i)}><div className="ibtop"><Pill>{i.priority}</Pill><Pill>{i.status}</Pill><span>{i.createdDate||''}</span></div><b>{i.code}</b><div className="ibfoot"><span>{i.project||i.customer}</span><span>{i.owner}</span></div></div>)}{!issues.filter(i=>i.status===k).length&&<div className="ibempty">拖拽卡片到这里</div>}</div>)}</div>}
// ---- 4. 问题与经验库（B 模式：可编辑写回 Notion）----
function ExpDetail({entry,close,notice,refresh}:{entry:ExpEntry;close:()=>void;notice:(s:string)=>void;refresh:()=>void}){
 const [edit,setEdit]=useState(false),[busy,setBusy]=useState(false),[title,setTitle]=useState(entry.title||''),[detail,setDetail]=useState(entry.detail||''),[solution,setSolution]=useState(entry.solution||''),[note,setNote]=useState(entry.note||'');
 async function save(){setBusy(true);try{const r=await apiFetch(apiUrl('update-experience'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({notion_page_id:entry.id,title,detail,solution,note})});const e=await r.json().catch(()=>({}));if(!r.ok)notice(e.error||`保存失败 ${r.status}`);else{notice('已保存并写回 Notion');setEdit(false);refresh()}}finally{setBusy(false)}}
 return <div className="overlay" onClick={e=>{if(e.target===e.currentTarget)close()}}><div className="modal issuedetail"><div className="modalhead"><h2>{edit?'编辑经验条目':entry.title}</h2><button type="button" className="icon" onClick={close}><X/></button></div>
 <div className="idmeta">{[['问题类型',entry.type||'—'],['负责技术',entry.owner||'—'],['解决时间',entry.resolvedDate||'—']].map(([k,v])=><div key={k}><dt>{k}</dt><dd>{v}</dd></div>)}</div>
 <div className="idactions">{edit?<><button className="outline" onClick={()=>setEdit(false)}>取消</button><button className="primary" disabled={busy} onClick={save}>{busy?'保存中…':'保存到 Notion'}</button></>:<><button className="outline" onClick={()=>setEdit(true)}>编辑</button>{entry.pageUrl&&<a className="outline linkbtn" href={entry.pageUrl} target="_blank" rel="noreferrer">在 Notion 打开 ↗</a>}</>}</div>
 <div className="idbody">{edit?<><label className="edlabel">问题名称<input value={title} onChange={e=>setTitle(e.target.value)}/></label><label className="edlabel">细节<textarea rows={4} value={detail} onChange={e=>setDetail(e.target.value)}/></label><label className="edlabel">解决方案<textarea rows={4} value={solution} onChange={e=>setSolution(e.target.value)}/></label><label className="edlabel">备注<input value={note} onChange={e=>setNote(e.target.value)}/></label></>:<><p><b>细节：</b>{entry.detail||'—'}</p><p><b>解决方案：</b>{entry.solution||'—'}</p><p><b>备注：</b>{entry.note||'—'}</p></>}</div>
 </div></div>}
function ExpBoard({rows,open,q,type}:{rows:ExpEntry[];open:(r:ExpEntry)=>void;q:string;type:string}){
 // 与 Notion「按问题类型看板」一致的分组视图（卡片含序号/解决时间/负责技术）
 const match=(r:ExpEntry)=>(!type||r.type===type)&&((r.title||'')+(r.detail||'')+(r.solution||'')).toLowerCase().includes(q.toLowerCase());
 const groups=Array.from(new Set(rows.map(r=>r.type).filter(Boolean) as string[]));
 const Card=(r:ExpEntry)=><div className="ibcard expcard" key={r.id} onClick={()=>open(r)}><div className="ibtop"><span>#{r.seq??'—'}</span><span>{r.resolvedDate||''}</span></div><b>{r.title||'（无标题）'}</b><div className="ibfoot"><span>{r.detail||''}</span><span>{r.owner||'—'}</span></div></div>;
 const cols:[string,ExpEntry[]][]=[...groups.map(g=>[g,rows.filter(r=>r.type===g&&match(r))] as [string,ExpEntry[]]),['未分类',rows.filter(r=>!r.type&&match(r))] as [string,ExpEntry[]]];
 return <div className="issueboard expboard">{cols.filter(([_,rs])=>rs.length).map(([g,rs])=><div className="ibcol" key={g}><div className="ibcolhead"><b>{g}</b><span>{rs.length}</span></div>{rs.map(Card)}</div>)}{!cols.some(([_,rs])=>rs.length)&&<div className="ibempty">暂无数据</div>}</div>}
function ExperiencePage({notice}:{notice:(s:string)=>void}){
 const [rows,setRows]=useState<ExpEntry[]>([]),[busy,setBusy]=useState(false),[q,setQ]=useState(''),[detail,setDetail]=useState<ExpEntry|null>(null),[type,setType]=useState(''),[view,setView]=useState<'table'|'board'>('table');
 async function load(autoSync=true){setBusy(true);try{if(autoSync)await apiFetch(apiUrl('sync-experience'),{method:'POST'});const {data,error}=await supabase!.from('notion_experience').select('*').order('seq',{ascending:true});if(error)notice(error.message);else setRows((data||[]).map((x:any)=>({id:x.notion_page_id,title:x.title,type:x.type,detail:x.detail,solution:x.solution,resolvedDate:x.resolved_date,owner:x.owner,note:x.note,seq:x.seq,pageUrl:x.page_url})))}finally{setBusy(false)}}
 useEffect(()=>{load(true)},[]);
 const filtered=rows.filter(r=>(!type||r.type===type)&&((r.title||'')+(r.detail||'')+(r.solution||'')).toLowerCase().includes(q.toLowerCase()));
 const types=Array.from(new Set(rows.map(r=>r.type).filter(Boolean) as string[]));
 return <><div className="title"><div><h1>问题与经验库</h1><p>与 Notion 同步 · 共 {rows.length} 条{busy?' · 同步中…':''}</p></div><div className="tabs issueviews"><button className={view==='table'?'active':''} onClick={()=>setView('table')}>表格视图</button><button className={view==='board'?'active':''} onClick={()=>setView('board')}>看板视图</button></div></div>
 <div className="issuefilters"><input className="ifsearch" placeholder="搜索经验…" value={q} onChange={e=>setQ(e.target.value)}/><span className="iflabel">类型</span>{['',...types].map(t=><button key={t||'all'} className={type===t?'iftag on':'iftag'} onClick={()=>setType(t)}>{t||'全部'}</button>)}</div>
 {view==='table'?<div className="card table"><div className="scroll"><table><thead><tr><th>问题名称</th><th>类型</th><th>负责技术</th><th>解决时间</th><th/></tr></thead><tbody>{filtered.map(r=><tr key={r.id} onClick={()=>setDetail(r)}><td><b>{r.title}</b></td><td>{r.type&&<Pill>{r.type}</Pill>}</td><td>{r.owner||'—'}</td><td>{r.resolvedDate||'—'}</td><td><button className="link">详情</button></td></tr>)}</tbody></table></div>{!filtered.length&&<Empty/>}</div>:<ExpBoard rows={rows} open={setDetail} q={q} type={type}/>}
 {detail&&<ExpDetail entry={detail} close={()=>setDetail(null)} notice={notice} refresh={()=>load(false)}/>}</>
}
// 30 秒轮询：页面切后台(document.hidden)自动暂停，离开页面(卸载)自动停止，回到前台立即补一次
function usePolling(fn:()=>void,ms=30000){useEffect(()=>{let timer:number|undefined;const tick=()=>{if(document.hidden)return;fn()};const onVis=()=>{if(!document.hidden)tick()};timer=window.setInterval(tick,ms);document.addEventListener('visibilitychange',onVis);return()=>{window.clearInterval(timer);document.removeEventListener('visibilitychange',onVis)}},[ms])}
function NpTable({rows,open}:{rows:NotionProject[];open:(p:NotionProject)=>void}){return <div className="card table"><div className="scroll"><table><thead><tr><th>项目</th><th>客户/现场</th><th>阶段</th><th>负责人</th><th>开始日期</th><th>里程碑</th><th/></tr></thead><tbody>{rows.map(p=><tr key={p.id} onClick={()=>open(p)}><td><b>{p.title}</b><span>{p.note||'暂无备注'}</span></td><td>{p.customer||'—'}</td><td><Pill>{p.stage||'—'}</Pill></td><td>{p.owner||'—'}</td><td>{p.startDate||'—'}</td><td>{p.milestone||'—'}</td><td><ChevronRight/></td></tr>)}</tbody></table></div>{!rows.length&&<Empty/>}</div>}
function ProjectDetail({p,close,notice,refresh}:{p:NotionProject;close:()=>void;notice:(s:string)=>void;refresh:()=>void}){
 const [edit,setEdit]=useState(false),[busy,setBusy]=useState(false),[note,setNote]=useState(p.note||''),[stage,setStage]=useState(p.stage||''),[owner,setOwner]=useState(p.owner||''),[customer,setCustomer]=useState(p.customer||'');
 async function save(){setBusy(true);try{const r=await apiFetch(apiUrl('update-project'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({notion_page_id:p.id,stage,owner,customer,note})});const e=await r.json().catch(()=>({}));if(!r.ok)notice(e.error||`保存失败 ${r.status}`);else{notice('已保存并写回 Notion');setEdit(false);refresh()}}finally{setBusy(false)}}
 const stages=['售前/需求确认','现场实施','调试交付','已验收','已结束'];
 const people=['Dongqi HE','Xincheng YE','Xian ZOU','Yuxing WANG','Yuqi LIU','Dian QU','其他'];
 return <div className="overlay" onClick={e=>{if(e.target===e.currentTarget)close()}}><div className="modal issuedetail"><div className="modalhead"><h2>{edit?'编辑项目':p.title}</h2><button type="button" className="icon" onClick={close}><X/></button></div>
 <div className="idmeta">{!edit&&[['客户/现场',p.customer||'—'],['阶段',p.stage||'—'],['项目负责人',p.owner||'—'],['开始日期',p.startDate||'—'],['里程碑',p.milestone||'—'],['备注',p.note||'—']].map(([k,v])=><div key={k}><dt>{k}</dt><dd>{v}</dd></div>)}</div>
 {edit&&<div className="formgrid" style={{padding:'0 24px 12px'}}>
   <label>阶段<select value={stage} onChange={e=>setStage(e.target.value)}>{stages.map(x=><option key={x}>{x}</option>)}</select></label>
   <label>项目负责人<select value={owner} onChange={e=>setOwner(e.target.value)}>{people.map(x=><option key={x}>{x}</option>)}</select></label>
   <label className="wide">客户/现场<input value={customer} onChange={e=>setCustomer(e.target.value)}/></label>
   <label className="wide">备注<textarea value={note} onChange={e=>setNote(e.target.value)}/></label>
 </div>}
 <div className="idactions">{edit?<><button className="outline" onClick={()=>setEdit(false)}>取消</button><button className="primary" disabled={busy} onClick={save}>{busy?'保存中…':'保存到 Notion'}</button></>:<><button className="outline" onClick={()=>setEdit(true)}>编辑</button>{p.pageUrl&&<a className="outline linkbtn" href={p.pageUrl} target="_blank" rel="noreferrer">在 Notion 打开 ↗</a>}</>}</div>
 </div></div>}
// ---- 总览：本周工作台（待办 todo + 按天按人完成/跟进汇总，数据源 notion_issues / notion_projects）----
function WeekWorkbench({notice,openIssue,onActiveIssues}:{notice:(s:string)=>void;openIssue:(i:NotionIssue)=>void;onActiveIssues:(xs:NotionIssue[])=>void}){
 const [issues,setIssues]=useState<NotionIssue[]>([]),[busy,setBusy]=useState(false),[dragging,setDragging]=useState<string|null>(null);
 // 性能优化：先查本地 Supabase 表立即渲染（毫秒级），Notion 同步放后台跑完再刷新。
 // 之前是"先等 Notion 全量同步完才查表"，导致总览每次要等好几秒。
 async function load(autoSync=true){setBusy(true);const query=async()=>{const {data,error}=await supabase!.from('notion_issues').select('*').order('created_date',{ascending:false});if(error)notice(error.message);else setIssues((data||[]).map((x:any)=>({id:x.notion_page_id,code:x.code,status:x.status,priority:x.priority,customer:x.customer,owner:x.owner,types:x.types||[],createdDate:x.created_date,resolvedDate:x.resolved_date,pageUrl:x.page_url,techDifficulty:x.tech_difficulty,dueDate:x.due_date,project:x.project,content:x.content,lastEdited:x.last_edited?String(x.last_edited).slice(0,10):null})))};try{if(autoSync){query();try{await apiFetch(apiUrl('sync'),{method:'POST'})}catch{};await query()}else await query()}finally{setBusy(false)}}
 useEffect(()=>{load(true)},[]);
 // 轮询只刷本地表（快）；Notion 全量同步降频为每 10 分钟一次
 const lastSyncRef=useRef(0);
 usePolling(()=>{if(Date.now()-lastSyncRef.current>600000){lastSyncRef.current=Date.now();load(true)}else load(false)},60000);
 const short=(code:string)=>code.replace(/_\d{4}(?=\d{2}-)|_(未解决|WellDone|Closed|新包已解决|等待rtas日志|等待RCS研发回复)$/g,'');
 const today=new Date().toISOString().slice(0,10);
 // 本周工作日（往前推7天取工作日，跳过周六周日）
 const weekDays=[...Array(10)].map((_,k)=>{const d=new Date();d.setDate(d.getDate()-(9-k));return d.toISOString().slice(0,10)}).filter(d=>{const day=new Date(d+'T12:00').getDay();return day!==0&&day!==6}).slice(-5);
 // 拖拽目标：'today'=今天要做(预计完成=今天) 'soon'=近期要做(清空预计完成) 日期=移到本周某天
 async function dragTo(id:string,target:string){
  const i=issues.find(x=>x.id===id);if(!i)return;
  // 'today' 转成真实日期字符串；'soon'=清空；其余 target 就是 YYYY-MM-DD
  const due=target==='soon'?null:target==='today'?new Date().toISOString().slice(0,10):target;
  if((i.dueDate||null)===due)return setDragging(null);
  // 乐观更新 + 双写（Supabase 由 edge function 顺带更新）
  setIssues(prev=>prev.map(x=>x.id===id?{...x,dueDate:due}:x));setDragging(null);
  try{const r=await apiFetch(apiUrl('update-due'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({notion_page_id:id,due_date:due})});const e=await r.json().catch(()=>({}));if(!r.ok){notice(e.error||`写回 Notion 失败 ${r.status}`);load(false)}else notice(due?`已把「${short(i.code||'')}」计划到 ${due}，已写回 Notion`:`「${short(i.code||'')}」已移回近期要做，已写回 Notion`)}catch{notice('网络错误，请重试');load(false)}
 }
 const dropZone=(target:string,children:React.ReactNode,extra?:string)=>(<div className={'wkdrop'+(extra||'')+(dragging?' droptarget':'')} onDragOver={e=>{e.preventDefault()}} onDrop={e=>{e.preventDefault();const id=e.dataTransfer.getData('text/plain');if(id)dragTo(id,target)}}>{children}</div>);
 const ownerColor=(o:string)=>{const i=['Dongqi','Xincheng','xincheng','Xian','Yuxing','Yuqi','Dian'].indexOf(o.split(' ')[0])+0;const soft=[['#eaf1fd','#1d4f9e'],['#e6f7f4','#0b6e60'],['#fdf1e0','#9a5a06'],['#f5edfd','#6b28c7'],['#fdeaea','#a51f1f'],['#eef1f5','#3c4656']][i]||['#eef1f5','#3c4656'];return soft};
 const Card=(i:NotionIssue,tag?:string)=>(<div className={'wkrow'+(dragging===i.id?' dragging':'')} key={i.id} draggable onDragStart={e=>{e.dataTransfer.setData('text/plain',i.id);setDragging(i.id)}} onDragEnd={()=>setDragging(null)} onClick={()=>openIssue(i)}><span className="wkowner" style={{background:ownerColor(i.owner)[0],color:ownerColor(i.owner)[1]}}>{i.owner||'—'}</span><div><b>{short(i.code||'')}</b><span>{i.project||i.customer}</span></div><Pill>{tag||i.status}</Pill></div>);
 // 分组依据：预计完成=今天 → 今天要做；未解决(Doing/Waiting)其余 → 近期要做；resolved 在本周 → 对应天
 const open=issues.filter(i=>i.status==='Doing'||i.status==='Waiting');
 useEffect(()=>{onActiveIssues(open)},[issues]);
 const todayDo=open.filter(i=>i.dueDate===today);
 const soon=open.filter(i=>!(i.dueDate===today));
 const done=issues.filter(i=>i.resolvedDate&&weekDays.includes(i.resolvedDate));
 return <><div className="wkgrid">
  <div className="card wkcard"><h3>📌 今天要做{busy?' · 同步中…':''}<small>拖拽卡片调整计划</small></h3>
   {dropZone('today',todayDo.length?todayDo.map(i=>Card(i)):<div className="idempty">把「近期要做」的卡片拖到这里 = 今天处理</div>,' minheight')}
   <div className="wkhint">= 预计完成日期 设为今天</div></div>
  <div className="card wkcard"><h3>🗂 近期要做 · 需跟进<small>拖拽卡片调整计划</small></h3>
   {dropZone('soon',soon.length?soon.map(i=>Card(i)):<div className="idempty">没有未解决的问题 🎉</div>,' minheight')}
   <div className="wkhint">= 清空预计完成日期</div></div>
  <div className="card wkcard wkwide"><h3>📅 本周完成情况（工作日 · 按人 · 按项目）<small>把卡片拖到某天 = 设那天的预计完成</small></h3>
   <div className="wkdays">{weekDays.map(d=>{const ds=done.filter(i=>i.resolvedDate===d);return <div className="wkdaycol" key={d}>{dropZone(d,<><div className="wkdayhead"><b>{d===today?'今天':new Date(d+'T12:00').toLocaleDateString('zh-CN',{weekday:'short'})} {d.slice(5)}</b><span>{ds.length} 项</span></div>{ds.length?ds.map(i=>Card(i,'Done')):<div className="idempty">—</div>}</>)}</div>})}</div>
  </div>
 </div></>
}
function ProjectsPage({notice,query,activeIssues}:{notice:(s:string)=>void;query:string;activeIssues?:NotionIssue[]}){
 const [rows,setRows]=useState<NotionProject[]>([]),[busy,setBusy]=useState(false),[detail,setDetail]=useState<NotionProject|null>(null);
 // 同 WeekWorkbench：先渲染本地表，Notion 同步后台跑
 async function load(autoSync=true){setBusy(true);const query=async()=>{const {data,error}=await supabase!.from('notion_projects').select('*').order('title');if(error)notice(error.message);else setRows((data||[]).map((x:any)=>({id:x.notion_page_id,title:x.title,customer:x.customer,stage:x.stage,owner:x.owner,startDate:x.start_date,milestone:x.milestone,note:x.note,pageUrl:x.page_url})))};try{if(autoSync){query();try{await apiFetch(apiUrl('sync-projects'),{method:'POST'})}catch{};await query()}else await query()}finally{setBusy(false)}}
 useEffect(()=>{load(true)},[]);
 // 轮询只刷本地表；Notion 全量同步降频 10 分钟
 const lastSyncRef=useRef(0);
 usePolling(()=>{if(!detail){if(Date.now()-lastSyncRef.current>600000){lastSyncRef.current=Date.now();load(true)}else load(false)}},30000);
 const filtered=rows.filter(p=>((p.title||'')+(p.customer||'')+(p.owner||'')+(p.note||'')).toLowerCase().includes(query.toLowerCase())&&(!activeIssues||activeIssues.some(i=>(i.project||'').includes(p.title||''))));
 return <><div className="title"><div><h1>项目</h1><p>与 Notion 项目管理库同步 · 共 {rows.length} 个{busy?' · 同步中…':''} · 每30秒自动同步 · 数据源为 Notion，网页编辑会写回</p></div></div>
 <NpTable rows={filtered} open={setDetail}/>{detail&&<ProjectDetail p={detail} close={()=>setDetail(null)} notice={notice} refresh={()=>{setDetail(null);load(false)}}/>}</>
}
// ---- 5/6. 技术资料库（A 模式只读）----
function DocsPage({db,label,notice}:{db:'official'|'unofficial';label:string;notice:(s:string)=>void}){
 const [rows,setRows]=useState<DocEntry[]>([]),[busy,setBusy]=useState(false),[q,setQ]=useState(''),[topic,setTopic]=useState(''),[cur,setCur]=useState<DocEntry|null>(null);
 function copyPath(path:string){navigator.clipboard.writeText(path).then(()=>notice('云盘路径已复制，去文件管理器粘贴'),()=>notice('复制失败，请手动选择复制'))}
 async function load(autoSync=true){setBusy(true);try{if(autoSync)await apiFetch(apiUrl(`sync-${db}`),{method:'POST'});const {data,error}=await supabase!.from(db==='official'?'notion_official_docs':'notion_unofficial_docs').select('*').order('title');if(error)notice(error.message);else setRows((data||[]).map((x:any)=>({id:x.notion_page_id,title:x.title,docNo:x.doc_no,topic:x.topic,module:x.module,platform:x.platform,language:x.language,version:x.version,scenarios:x.scenarios||[],audience:x.audience||[],field:x.field,keywords:x.keywords,sourceUrl:x.source_url,lastReview:x.last_review,pageUrl:x.page_url,docType:x.doc_type,execNature:x.exec_nature})))}finally{setBusy(false)}}
 useEffect(()=>{load(true)},[db]);
 const filtered=rows.filter(r=>(!topic||r.topic===topic)&&((r.title||'')+(r.docNo||'')+(r.keywords||'')).toLowerCase().includes(q.toLowerCase()));
 const topics=Array.from(new Set(rows.map(r=>r.topic).filter(Boolean) as string[]));
 return <><div className="title"><div><h1>{label}</h1><p>与 Notion 同步 · 共 {rows.length} 条{busy?' · 同步中…':''} · 只读</p></div></div>
 <div className="issuefilters"><input className="ifsearch" placeholder="搜索资料名称/编号/关键词…" value={q} onChange={e=>setQ(e.target.value)}/><span className="iflabel">主题</span>{['',...topics].map(t=><button key={t||'all'} className={topic===t?'iftag on':'iftag'} onClick={()=>setTopic(t)}>{t||'全部'}</button>)}</div>
 <div className="card table"><div className="scroll"><table><thead><tr><th>资料名称</th><th>编号</th><th>主题</th><th>模块</th><th>平台</th><th>语言</th>{db==='unofficial'&&<th>类型</th>}<th>审核</th><th/></tr></thead><tbody>{filtered.map(r=><tr key={r.id} onClick={()=>setCur(r)}><td><b>{r.title}</b></td><td>{r.docNo||'—'}</td><td>{r.topic&&<Pill>{r.topic}</Pill>}</td><td>{r.module||'—'}</td><td>{r.platform||'—'}</td><td>{r.language||'—'}</td>{db==='unofficial'&&<td>{r.docType&&<Pill>{r.docType}</Pill>}</td>}<td>{r.lastReview||'—'}</td><td><button className="link">路径</button></td></tr>)}</tbody></table></div>{!filtered.length&&<Empty/>}</div>
 {cur&&<div className="overlay" onClick={e=>{if(e.target===e.currentTarget)setCur(null)}}><div className="modal small docpath"><div className="modalhead"><h2>{cur.title}</h2><button type="button" className="icon" onClick={()=>setCur(null)}><X/></button></div>
 <div className="pathbox"><span className="pathlabel">OneDrive 路径</span><code>{cur.sourceUrl||'（此资料未登记路径）'}</code></div>
 <div className="actions"><button className="outline" onClick={()=>setCur(null)}>关闭</button>{cur.sourceUrl&&<button className="primary" onClick={()=>copyPath(cur.sourceUrl!)}>复制路径</button>}</div>
 </div></div>}
</>
}
// ---- 员工出勤日历（Notion 员工出勤记录库镜像，时间线+表格视图）----
function AttendancePage({notice}:{notice:(s:string)=>void}){
 const [rows,setRows]=useState<AttEntry[]>([]),[busy,setBusy]=useState(false),[view,setView]=useState<'timeline'|'table'>('timeline'),[month,setMonth]=useState<string>('');
 // 先查本地 Supabase 表立即渲染，sync-attendance 放后台（与其他镜像页一致）
 async function load(autoSync=true){setBusy(true);const query=async()=>{const {data,error}=await supabase!.from('notion_attendance').select('*').order('start_date');if(error)notice(error.message);else setRows((data||[]).map((x:any)=>({id:x.notion_page_id,title:x.title||'',person:x.person,type:x.type,place:x.place,startDate:x.start_date,endDate:x.end_date,status:x.status,note:x.note,pageUrl:x.page_url})))};try{if(autoSync){query();try{await apiFetch(apiUrl('sync-attendance'),{method:'POST'})}catch{};await query()}else await query()}finally{setBusy(false)}}
 useEffect(()=>{load(true)},[]);
 // 月份选项：从数据里所有起止日期取年月
 const months=Array.from(new Set(rows.flatMap(r=>[r.startDate,r.endDate].filter(Boolean) as string[]).map(d=>d.slice(0,7)))).sort().reverse();
 // 时间线范围：选中月的前一月1号 ~ 后一月月底（保证跨月条完整显示），未选则全部数据的 min~max 外扩一月
 const range=useMemo(()=>{
  const all=rows.flatMap(r=>[r.startDate,r.endDate].filter(Boolean) as string[]);
  if(!all.length)return null;
  let lo=month?`${month}-01`:all.slice().sort()[0],hi=month?`${month}-01`:all.slice().sort().reverse()[0];
  if(month){const m=new Date(month+'-01T12:00');m.setMonth(m.getMonth()+1);hi=new Date(m.getTime()-864e5).toISOString().slice(0,10)}
  const start=new Date(lo);start.setDate(1);start.setMonth(start.getMonth()-0);
  const end=new Date(hi);end.setMonth(end.getMonth()+1);end.setDate(0);
  return {start: new Date(start.getTime()-(start.getTimezoneOffset()*60000)).toISOString().slice(0,10), end:new Date(end.getTime()-(end.getTimezoneOffset()*60000)).toISOString().slice(0,10)};
 },[rows,month]);
 const days=useMemo(()=>{const out:string[]=[];if(!range)return out;const d=new Date(range.start+'T12:00');const e=new Date(range.end+'T12:00');while(d<=e){out.push(new Date(d).toISOString().slice(0,10));d.setDate(d.getDate()+1)}return out},[range]);
 const people=Array.from(new Set(rows.map(r=>r.person).filter(Boolean) as string[]));
 const filtered=month?rows.filter(r=>r.startDate&&r.startDate.slice(0,7)<=month&&(!r.endDate||r.endDate.slice(0,7)>=month.slice(0,7))||r.startDate?.slice(0,7)===month||r.endDate?.slice(0,7)===month):rows;
 const fmt=(s:string)=>s.slice(5).replace('-','/');
 const W=26;
 const pos=(s:string,e:string)=>{if(!range)return null;const a=Math.max(0,Math.round((new Date(s+'T12:00').getTime()-new Date(range.start+'T12:00').getTime())/864e5));const b=Math.min(days.length-1,Math.round((new Date(e+'T12:00').getTime()-new Date(range.start+'T12:00').getTime())/864e5));if(b<0||a>days.length-1)return null;return {a,b}};
 return <><div className="title"><div><h1>员工出勤日历</h1><p>与 Notion 员工出勤记录同步 · 共 {rows.length} 条{busy?' · 同步中…':''}</p></div><div className="tabs issueviews"><button className={view==='timeline'?'active':''} onClick={()=>setView('timeline')}>时间线视图</button><button className={view==='table'?'active':''} onClick={()=>setView('table')}>表格视图</button></div></div>
 <div className="issuefilters"><span className="iflabel">月份</span><button className={!month?'iftag on':'iftag'} onClick={()=>setMonth('')}>全部</button>{months.map(m=><button key={m} className={month===m?'iftag on':'iftag'} onClick={()=>setMonth(m)}>{m}</button>)}</div>
 {view==='timeline'&&days.length>0?<div className="card table atttl"><div className="scroll"><table className="tltable"><thead><tr><th className="tlname">人员</th>{(()=>{let cm='';let span=0;const cells:{m:string;span:number}[]=[];days.forEach(d=>{const m=d.slice(0,7);if(m!==cm){if(cm)cells.push({m:cm,span});cm=m;span=1}else span++});cells.push({m:cm,span});return cells.map(c=><th key={c.m} colSpan={c.span} className="tlmonth">{c.m.replace('-','年')}月</th>)})()}</tr><tr><th className="tlname"/>{days.map(d=><th key={d} className={(new Date(d+'T12:00').getDay()===0||new Date(d+'T12:00').getDay()===6)?'tlwk':''}>{+d.slice(8,10)===1||+d.slice(8,10)%5===0?d.slice(8,10):'·'}</th>)}</tr></thead>
  <tbody>{people.map(p=><tr key={p}><th className="tlname">{p}</th>{days.map(d=>{const dow=new Date(d+'T12:00').getDay();return <td key={d} className={dow===0||dow===6?'tlwk':''}/>})}<td className="tlcells">{rows.filter(r=>r.person===p&&r.startDate&&r.endDate).map(r=>{const q=pos(r.startDate!,r.endDate!);if(!q)return null;return <div key={r.id} className={'tlbar '+(r.type==='请假'?'leave':'trip')} style={{left:`calc(var(--tlw)*${q.a})`,width:`calc(var(--tlw)*${q.b-q.a+1} - 4px)`}} title={`${r.type||'—'} ${r.place||''} ${fmt(r.startDate!)}–${fmt(r.endDate!)}`}><span>{r.type}{r.place?` · ${r.place}`:''} {fmt(r.startDate!)}–{fmt(r.endDate!)}</span></div>})}</td></tr>)}</tbody></table></div></div>
 :<div className="card table"><div className="scroll"><table><thead><tr><th>人员</th><th>类型</th><th>地点</th><th>开始</th><th>结束</th><th>状态</th><th/></tr></thead><tbody>{filtered.map(r=><tr key={r.id}><td><b>{r.person||'—'}</b></td><td>{r.type&&<Pill>{r.type}</Pill>}</td><td>{r.place||'—'}</td><td>{r.startDate||'—'}</td><td>{r.endDate||'—'}</td><td>{r.status&&<Pill>{r.status}</Pill>}</td><td>{r.pageUrl&&<a className="outline linkbtn" href={r.pageUrl} target="_blank" rel="noreferrer">Notion ↗</a>}</td></tr>)}</tbody></table></div>{!filtered.length&&<Empty/>}</div>}
 </>}
function SkillsPage({notice}:{notice:(s:string)=>void}){
 const [rows,setRows]=useState<SkillEntry[]>([]),[busy,setBusy]=useState(false),[cat,setCat]=useState(''),[q,setQ]=useState('');
 async function load(autoSync=true){setBusy(true);try{if(autoSync)await apiFetch(apiUrl('sync-skills'),{method:'POST'});const {data,error}=await supabase!.from('notion_skills').select('*').order('seq',{ascending:true});if(error)notice(error.message);else setRows((data||[]).map((x:any)=>({id:x.notion_page_id,title:x.title,category:x.category,seq:x.seq,dongqi:x.dongqi,xincheng:x.xincheng,xian:x.xian,yuxing:x.yuxing,yuqi:x.yuqi,dian:x.dian,note:x.note,pageUrl:x.page_url})))}finally{setBusy(false)}}
 useEffect(()=>{load(true)},[]);
 const filtered=rows.filter(r=>(!cat||r.category===cat)&&(r.title||'').toLowerCase().includes(q.toLowerCase()));
 const cats=Array.from(new Set(rows.map(r=>r.category).filter(Boolean) as string[]));
 const okn=(v:string|null)=><span className={'pill '+(v==='OK'?'green':v==='NOK'?'red':'')}>{v||'—'}</span>;
 const people=[['Dongqi','dongqi'],['Xincheng','xincheng'],['Xian','xian'],['Yuxing','yuxing'],['Yuqi','yuqi'],['Dian','dian']] as const;
 const stats=people.map(([n,k])=>({n,ok:rows.filter(r=>r[k as keyof SkillEntry]==='OK').length,total:rows.filter(r=>r[k as keyof SkillEntry]).length}));
 return <><div className="title"><div><h1>团队能力矩阵</h1><p>与 Notion 同步 · 共 {rows.length} 项 · 只读{busy?' · 同步中…':''}</p></div></div>
 <section className="stats">{stats.map(s=><div className="stat" key={s.n}><span>{s.n}</span><strong>{s.ok}/{s.total}</strong><small>OK 技能数</small></div>)}</section>
 <div className="issuefilters"><input className="ifsearch" placeholder="搜索技能项…" value={q} onChange={e=>setQ(e.target.value)}/><span className="iflabel">类别</span>{['',...cats].map(c=><button key={c||'all'} className={cat===c?'iftag on':'iftag'} onClick={()=>setCat(c)}>{c||'全部'}</button>)}</div>
 <div className="card table"><div className="scroll"><table><thead><tr><th>#</th><th>技能项</th>{people.map(([n])=><th key={n}>{n}</th>)}<th>备注</th></tr></thead><tbody>{filtered.map(r=><tr key={r.id}><td>{r.seq??'—'}</td><td><b>{r.title}</b></td><td>{okn(r.dongqi)}</td><td>{okn(r.xincheng)}</td><td>{okn(r.xian)}</td><td>{okn(r.yuxing)}</td><td>{okn(r.yuqi)}</td><td>{okn(r.dian)}</td><td>{r.note||'—'}</td></tr>)}</tbody></table></div>{!filtered.length&&<Empty/>}</div></>
}

function IssueTable({issues,open}:{issues:NotionIssue[];open:(i:NotionIssue)=>void}){return <div className="card table"><div className="scroll"><table><thead><tr><th>编号/标题</th><th>所属项目</th><th>客户</th><th>负责人</th><th>类型</th><th>优先级</th><th>技术难度</th><th>状态</th><th>创建</th><th>解决</th><th>最后更新</th><th/></tr></thead><tbody>{issues.map(i=><tr key={i.id} onClick={()=>open(i)}><td><b>{i.code}</b></td><td>{i.project||'—'}</td><td>{i.customer}</td><td>{i.owner}</td><td>{i.types.map(t=><span className="pill" key={t}>{t}</span>)}</td><td><Pill>{i.priority}</Pill></td><td><Pill>{i.techDifficulty||'—'}</Pill></td><td><Pill>{i.status}</Pill></td><td>{i.createdDate||'—'}</td><td>{i.resolvedDate||'—'}</td><td>{i.lastEdited||'—'}</td><td><button className="link" onClick={e=>{e.stopPropagation();open(i)}}>详情</button></td></tr>)}</tbody></table></div>{!issues.length&&<Empty/>}</div>}
export default function App(){const [session,setSession]=useState<Session|null>(null),[loading,setLoading]=useState(true),[busy,setBusy]=useState(false),[page,setPage]=useState<Page>('dashboard'),[menu,setMenu]=useState(false),[query,setQuery]=useState(''),[projects,setProjects]=useState<Project[]>([]),[items,setItems]=useState<Item[]>([]),[issues,setIssues]=useState<NotionIssue[]>([]),[activeIssues,setActiveIssues]=useState<NotionIssue[]>([]),[issueView,setIssueView]=useState<IssueView>('table'),[issueFilters,setIssueFilters]=useState<IssueFilters>({status:'',priority:'',owner:'',difficulty:''}),[selected,setSelected]=useState<Project|null>(null),[pform,setPform]=useState(false),[iform,setIform]=useState(false),[notice,setNotice]=useState(''),[detail,setDetail]=useState<NotionIssue|null>(null),[dragging,setDragging]=useState<string|null>(null);
useEffect(()=>{if(!supabase){setLoading(false);return}supabase.auth.getSession().then(x=>{setSession(x.data.session);setApiToken(x.data.session?.access_token??null);setLoading(false)});const {data}=supabase.auth.onAuthStateChange((_e,s)=>{setSession(s);setApiToken(s?.access_token??null)});return()=>data.subscription.unsubscribe()},[]);
async function loadProjects(){if(!supabase)return;setBusy(true);const {data,error}=await supabase.from('projects').select('*').order('created_at',{ascending:false});setBusy(false);if(error)setNotice(msg(error));else setProjects((data||[]) as Project[])}
async function loadItems(){if(!supabase||page==='dashboard'||page==='projects'||page==='issues'||page==='experience'||page==='attendance'||page==='official'||page==='unofficial'/*||page==='skills' 2026-11-27 暂时隐藏团队能力矩阵*/)return;setBusy(true);const {data,error}=await supabase.from(tables[page]).select('*').order('created_at',{ascending:false});setBusy(false);if(error)setNotice(msg(error));else setItems((data||[]).map((x:any)=>({id:x.id,projectId:x.project_id,title:x.title,detail:x.detail||x.objective||x.notes||x.mitigation||x.category,status:x.status||x.result||(x.completed?'已完成':'待完成'),priority:x.priority||x.severity}))) }
async function syncFromNotion(){try{const r=await apiFetch(apiUrl('sync'),{method:'POST'});if(!r.ok){const e=await r.json().catch(()=>({}));setNotice(e.error||`Notion 同步失败 ${r.status}`)}}catch{}}
async function loadIssues(autoSync=true){if(!supabase)return;if(autoSync)await syncFromNotion();setBusy(true);const {data,error}=await supabase.from('notion_issues').select('*').order('created_date',{ascending:false});setBusy(false);if(error)setNotice(msg(error));else setIssues((data||[]).map((x:any)=>({id:x.notion_page_id,code:x.code,status:x.status,priority:x.priority,customer:x.customer,owner:x.owner,types:x.types||[],createdDate:x.created_date,resolvedDate:x.resolved_date,pageUrl:x.page_url,techDifficulty:x.tech_difficulty,dueDate:x.due_date,project:x.project,lastEdited:x.last_edited?String(x.last_edited).slice(0,10):null,content:x.content})))}
useEffect(()=>{if(session)loadProjects()},[session]);useEffect(()=>{if(session)loadItems()},[session,page]);useEffect(()=>{if(session&&page==='issues')loadIssues(true)},[session,page]);const rows=useMemo(()=>projects.filter(p=>(p.name+p.customer+(p.description||'')).toLowerCase().includes(query.toLowerCase())),[projects,query]);
const issueRows=useMemo(()=>issues.filter(i=>(!issueFilters.status||i.status===issueFilters.status)&&(!issueFilters.priority||i.priority===issueFilters.priority)&&(!issueFilters.owner||i.owner===issueFilters.owner)&&(!issueFilters.difficulty||i.techDifficulty===issueFilters.difficulty)&&(i.code+i.customer+i.owner+i.project+(i.types||[]).join()).toLowerCase().includes(query.toLowerCase())),[issues,issueFilters,query]);
async function updateIssueStatus(id:string,status:string){if(!supabase)return;setBusy(true);try{const {error}=await supabase.from('notion_issues').update({status}).eq('notion_page_id',id);if(error){setNotice(msg(error));return}setIssues(prev=>prev.map(i=>i.id===id?{...i,status}:i));const r=await apiFetch(apiUrl('update-status'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({notion_page_id:id,status})});if(!r.ok){const e=await r.json().catch(()=>({}));setNotice(e.error||`写回 Notion 失败 ${r.status}`)}else setNotice('状态已更新并写回 Notion');loadIssues(false)}finally{setBusy(false)}}
async function delProject(){if(!supabase||!selected||!confirm(`确认永久删除“${selected.name}”及关联数据吗？`))return;const {error}=await supabase.from('projects').delete().eq('id',selected.id);if(error)setNotice(msg(error));else{setSelected(null);loadProjects()}}
async function delItem(id:string){if(!supabase||!(page in tables)||!confirm('确认永久删除这条记录吗？'))return;const tbl=(tables as Record<string,string>)[page];const {error}=await supabase.from(tbl).delete().eq('id',id);if(error)setNotice(msg(error));else loadItems()}
if(loading)return <div className="center"><Loader2 className="spin"/>正在连接…</div>;if(!supabase)return <div className="center">缺少 Supabase 环境变量</div>;if(!session)return <Auth/>;const name=session.user.user_metadata.full_name||session.user.email?.split('@')[0]||'用户';
return <div className="app"><aside className={menu?'open':''}><div className="brand"><div className="mark">H</div><div><b>AMR PROJECT</b><span>MANAGEMENT SYSTEM</span></div><button className="close" onClick={()=>setMenu(false)}><X/></button></div><nav>{nav.map(([id,label,I])=><button key={id} className={page===id&&!selected?'active':''} onClick={()=>{setPage(id);setSelected(null);setMenu(false)}}><I/>{label}</button>)}</nav><button className="sidefoot" onClick={()=>supabase?.auth.signOut()}><div className="avatar">{name.slice(0,2)}</div><div><b>{name}</b><span>{session.user.email}</span></div><LogOut/></button></aside><main><header><button className="menubtn" onClick={()=>setMenu(true)}><Menu/></button><div className="search"><Search/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="搜索项目、客户…"/></div><div className="cloud"><i className="on"/>云端已连接</div><button className="icon"><Bell/></button><div className="avatar">{name.slice(0,2)}</div></header><div className="content">{notice&&<div className="toast error">{notice}<button onClick={()=>setNotice('')}>×</button></div>}{busy&&<div className="loadingbar"/>}{selected?<><button className="back" onClick={()=>setSelected(null)}>← 返回项目</button><div className="projecthero"><div><span className="eyebrow">{selected.customer} / AMR PROJECT</span><h1>{selected.name}</h1><p>{selected.description||'暂无说明'}</p></div><div><Pill>{selected.status}</Pill><strong>{selected.progress}%</strong><span>总体进度</span></div></div><div className="detailactions"><button className="outline" onClick={()=>setPform(true)}>编辑项目</button><button className="danger" onClick={delProject}>删除项目</button></div><div className="card info"><h3>项目基本信息</h3><dl><div><dt>开始日期</dt><dd>{selected.start_date||'—'}</dd></div><div><dt>计划交付</dt><dd>{selected.delivery_date||'—'}</dd></div><div><dt>当前阶段</dt><dd>{selected.status}</dd></div><div><dt>风险等级</dt><dd>{selected.risk}</dd></div></dl></div></>:page==='dashboard'?<><Title name="项目总览" sub="数据实时来自 Notion · 每60秒自动同步 · 只显示有待跟进问题的项目" add={()=>setPform(true)}/><WeekWorkbench notice={setNotice} openIssue={setDetail} onActiveIssues={setActiveIssues}/><ProjectsPage notice={setNotice} query={query} activeIssues={activeIssues}/></>:page==='projects'?<ProjectsPage notice={setNotice} query={query}/>:page==='issues'?<><div className="title"><div><h1>问题追踪看板 (issue-tracker)</h1><p>与 Notion 问题追踪同步 · 共 {issues.length} 条，当前显示 {issueRows.length} 条</p></div><div className="tabs issueviews"><button className={issueView==='table'?'active':''} onClick={()=>setIssueView('table')}>表格视图</button><button className={issueView==='board'?'active':''} onClick={()=>setIssueView('board')}>看板视图</button></div></div><IssueFiltersBar issues={issues} filters={issueFilters} set={setIssueFilters}/>{issueView==='table'?<IssueTable issues={issueRows} open={setDetail}/>:<IssueBoard issues={issueRows} open={setDetail} dragEnd={(id,s)=>updateIssueStatus(id,s)} dragging={dragging} setDragging={setDragging}/>}</>:page==='experience'?<ExperiencePage notice={setNotice}/>:page==='attendance'?<AttendancePage notice={setNotice}/>:page==='official'?<DocsPage db="official" label="官方技术资料" notice={setNotice}/>:page==='unofficial'?<DocsPage db="unofficial" label="非官方技术资料" notice={setNotice}/>/*:page==='skills'?<SkillsPage notice={setNotice}/> 2026-11-27 暂时隐藏团队能力矩阵，需要时解开此注释恢复*/:<><Title name={titles[page]} sub="真实数据已与 Supabase 同步" add={()=>setIform(true)}/><div className="card list">{items.map(i=><div className="listrow" key={i.id}><code>{i.id.slice(0,8)}</code><div><b>{i.title}</b><span>{projects.find(p=>p.id===i.projectId)?.name||'未关联'} · {i.detail||'暂无说明'}</span></div>{i.priority&&<Pill>{i.priority}</Pill>}<Pill>{i.status}</Pill><button className="textdanger" onClick={()=>delItem(i.id)}>删除</button></div>)}{!items.length&&<Empty/>}</div></>}</div></main>{pform&&<ProjectForm value={selected||undefined} close={()=>setPform(false)} saved={()=>{loadProjects();setSelected(null)}} notice={setNotice}/>} {iform&&page!=='dashboard'&&page!=='projects'&&page!=='issues'&&page!=='experience'&&page!=='official'&&page!=='unofficial'/*&&page!=='skills' 2026-11-27 暂时隐藏团队能力矩阵*/&&<ItemForm page={page as any} projects={projects} close={()=>setIform(false)} saved={loadItems} notice={setNotice}/>} {detail&&<IssueDetail issue={detail} close={()=>setDetail(null)} notice={setNotice} refresh={()=>{setDetail({...detail});loadIssues(false)}}/>}</div>}
